{"filename": "test_compact.py", "content": "import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
compact_whitespace = target.compact_whitespace


def test_strips_each_line():
    assert compact_whitespace(["  hello  ", "world"]) == ["hello", "world"]


def test_omits_whitespace_only_lines():
    assert compact_whitespace(["a", "   ", "\t", "b", " \t\n "]) == ["a", "b"]


def test_preserves_order():
    assert compact_whitespace(["  z", "  a", "  m"]) == ["z", "a", "m"]


def test_empty_list():
    assert compact_whitespace([]) == []


def test_all_whitespace_empty():
    assert compact_whitespace(["", "  ", "\t", " \n "]) == []


def test_removes_trailing_newlines():
    assert compact_whitespace(["line1\n", "line2\n"]) == ["line1", "line2"]


def test_internal_whitespace_preserved():
    assert compact_whitespace(["a   b\tc"]) == ["a   b\tc"]


def test_single_string_line():
    assert compact_whitespace(["  x  "]) == ["x"]
"}

