merge_inventory = target.merge_inventory


def test_no_overlap():
    """Non-overlapping SKUs: result contains all SKUs from both dicts."""
    base = {"A": 1, "B": 2}
    incoming = {"C": 3, "D": 4}
    result = merge_inventory(base, incoming)
    assert result == {"A": 1, "B": 2, "C": 3, "D": 4}


def test_overlap_counts_added():
    """Matching SKUs should have their counts added together."""
    base = {"A": 5, "B": 3}
    incoming = {"B": 7, "C": 1}
    result = merge_inventory(base, incoming)
    assert result == {"A": 5, "B": 10, "C": 1}


def test_both_empty():
    """Two empty dicts produce an empty dict."""
    result = merge_inventory({}, {})
    assert result == {}


def test_base_empty():
    """Empty base returns a copy of incoming."""
    base = {}
    incoming = {"X": 10}
    result = merge_inventory(base, incoming)
    assert result == {"X": 10}


def test_incoming_empty():
    """Empty incoming returns a copy of base."""
    base = {"Y": 20}
    incoming = {}
    result = merge_inventory(base, incoming)
    assert result == {"Y": 20}


def test_base_not_mutated():
    """Base dictionary should not be mutated."""
    base = {"A": 1, "B": 2}
    base_copy = copy.deepcopy(base)
    incoming = {"A": 10, "C": 5}
    merge_inventory(base, incoming)
    assert base == base_copy


def test_incoming_not_mutated():
    """Incoming dictionary should not be mutated."""
    incoming = {"A": 10, "C": 5}
    incoming_copy = copy.deepcopy(incoming)
    base = {"A": 1, "B": 2}
    merge_inventory(base, incoming)
    assert incoming == incoming_copy


def test_returns_new_dict():
    """Result must be a new dict, not the same object as either input."""
    base = {"A": 1}
    incoming = {"B": 2}
    result = merge_inventory(base, incoming)
    assert result is not base
    assert result is not incoming


def test_zero_counts_allowed():
    """Counts must be non-negative integers, so zero is valid."""
    base = {"A": 0}
    incoming = {"B": 0}
    result = merge_inventory(base, incoming)
    assert result == {"A": 0, "B": 0}


