    assert result == {"A": 5}


def test_multiple_overlaps():
    """Multiple overlapping SKUs all get their counts summed."""
    base = {"A": 1, "B": 2, "C": 3}
    incoming = {"A": 10, "B": 20, "C": 30, "D": 40}
    result = merge_inventory(base, incoming)
    assert result == {"A": 11, "B": 22, "C": 33, "D": 40}


