        pass


def test_negative_count_in_incoming():
    """Negative count in incoming dict raises ValueError."""
    try:
        merge_inventory({"A": 1}, {"B": -5})
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_non_int_count_raises_typeerror():
    """Counts must be integers; float raises TypeError."""
    try:
        merge_inventory({"A": 1.5}, {"B": 2})
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_empty_sku_raises_valueerror():
    """SKU must be a non-empty string; empty string raises ValueError."""
    try:
        merge_inventory({"": 1}, {"B": 2})
        assert False, "Expected ValueError"
    except ValueError:
        pass


